import{_ as c,C as t,o as d,c as l,a6 as s,E as n,j as a,a as i}from"./chunks/framework.5dd0l9Wo.js";const f=JSON.parse('{"title":"Web Cache Poisoning","description":"Unkeyed inputs, cache-key confusion, parameter cloaking, fat GET, cache key injection, and internal caches.","frontmatter":{"title":"Web Cache Poisoning","description":"Unkeyed inputs, cache-key confusion, parameter cloaking, fat GET, cache key injection, and internal caches."},"headers":[],"relativePath":"cache-poisoning/index.md","filePath":"cache-poisoning/index.md"}'),h={name:"cache-poisoning/index.md"};function p(u,e,g,m,b,y){const o=t("LabGroup"),r=t("TopicComplete");return d(),l("div",null,[e[0]||(e[0]=s(`<h1 id="web-cache-poisoning" tabindex="-1">Web Cache Poisoning <a class="header-anchor" href="#web-cache-poisoning" aria-label="Permalink to &quot;Web Cache Poisoning&quot;">​</a></h1><p class="wd-section-lede">A cache is a shared copy of a response. Poisoning means making that shared copy contain attacker-controlled content, so every user who requests the key receives it. The bug is an input that affects the response but not the cache key.</p><div class="wd-callout"><p><strong>The model.</strong> Cache key = the request attributes the cache uses to identify a stored response (usually method, host, path, and sometimes query). If an input changes the response but is absent from the key, an attacker can prime the cache through their own request and the next victim gets the poisoned response.</p></div><h2 id="cache-keys-and-unkeyed-inputs" tabindex="-1">Cache keys and unkeyed inputs <a class="header-anchor" href="#cache-keys-and-unkeyed-inputs" aria-label="Permalink to &quot;Cache keys and unkeyed inputs&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /en?cb=1</span></span>
<span class="line"><span>X-Forwarded-Host: attacker.example</span></span>
<span class="line"><span></span></span>
<span class="line"><span>cache key: /en?cb=1</span></span>
<span class="line"><span>response:  &lt;script src=&quot;https://attacker.example/tracking.js&quot;&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>The <code>X-Forwarded-Host</code> header is <strong>unkeyed</strong>: the cache stores one response for <code>/en?cb=1</code>, and that response now points at the attacker&#39;s script for everyone.</p>`,6)),n(o,{ids:"cache-poisoning-lab-web-cache-poisoning-with-an-unkeyed-header, cache-poisoning-lab-web-cache-poisoning-with-an-unkeyed-cookie, cache-poisoning-lab-web-cache-poisoning-with-multiple-headers"}),e[1]||(e[1]=s('<details class="details custom-block"><summary>🔬 Under the Hood: how to find unkeyed inputs</summary><ol><li>Choose a static, cacheable page.</li><li>Send requests with candidate headers (<code>X-Forwarded-Host</code>, <code>X-Forwarded-Scheme</code>, <code>X-Host</code>, <code>X-Original-URL</code>, <code>Forwarded</code>) and cache-busting query parameters.</li><li>Compare responses for reflection or behaviour changes.</li><li>Remove the cache buster and request the same URL repeatedly to see whether the poisoned response sticks.</li></ol><p>A header that changes the response is not automatically exploitable; it must be cacheable and the change must be persistent for the key.</p></details><h2 id="targeted-poisoning-and-unknown-headers" tabindex="-1">Targeted poisoning and unknown headers <a class="header-anchor" href="#targeted-poisoning-and-unknown-headers" aria-label="Permalink to &quot;Targeted poisoning and unknown headers&quot;">​</a></h2><p>Some headers only affect a subset of users, or only appear in a specific flow. A targeted attack uses a header the victim&#39;s browser or an intermediary will send, and an unknown header may be the only unkeyed one.</p>',3)),n(o,{ids:"cache-poisoning-lab-web-cache-poisoning-targeted-using-an-unknown-header"}),e[2]||(e[2]=s('<h2 id="query-parameters-and-cloaking" tabindex="-1">Query parameters and cloaking <a class="header-anchor" href="#query-parameters-and-cloaking" aria-label="Permalink to &quot;Query parameters and cloaking&quot;">​</a></h2><ul><li><strong>Unkeyed query string:</strong> the cache ignores the whole query, so <code>?utm=...</code> can carry a payload.</li><li><strong>Unkeyed parameter:</strong> one parameter is excluded from the key while still being reflected.</li><li><strong>Parameter cloaking:</strong> a delimiter (<code>;</code>, <code>&amp;</code>, encoded <code>#</code>) makes the cache and the origin parse different parameter sets.</li><li><strong>Fat GET:</strong> a body on a GET is ignored by the cache key but processed by the origin.</li></ul>',2)),n(o,{ids:"cache-poisoning-lab-web-cache-poisoning-unkeyed-query, cache-poisoning-lab-web-cache-poisoning-unkeyed-param, cache-poisoning-lab-web-cache-poisoning-param-cloaking, cache-poisoning-lab-web-cache-poisoning-fat-get"}),e[3]||(e[3]=a("h2",{id:"normalisation-and-cache-key-injection",tabindex:"-1"},[i("Normalisation and cache key injection "),a("a",{class:"header-anchor",href:"#normalisation-and-cache-key-injection","aria-label":'Permalink to "Normalisation and cache key injection"'},"​")],-1)),e[4]||(e[4]=a("p",null,"If the cache normalises the path but the origin does not (or vice versa), two different raw URLs can map to one key. Cache key injection goes further: an attacker-controlled value is placed in a header that the cache includes in the key, allowing them to target a victim's specific cache entry.",-1)),n(o,{ids:"cache-poisoning-lab-web-cache-poisoning-normalization, cache-poisoning-lab-web-cache-poisoning-cache-key-injection"}),e[5]||(e[5]=a("h2",{id:"chaining-and-dom-sinks",tabindex:"-1"},[i("Chaining and DOM sinks "),a("a",{class:"header-anchor",href:"#chaining-and-dom-sinks","aria-label":'Permalink to "Chaining and DOM sinks"'},"​")],-1)),e[6]||(e[6]=a("p",null,"A cached response can poison a DOM XSS sink: the cache stores a page whose JavaScript reads a reflected value. Strict cacheability criteria (only certain extensions) can still be satisfied by a crafted path.",-1)),n(o,{ids:"cache-poisoning-lab-web-cache-poisoning-to-exploit-a-dom-vulnerability-via-a-cache-with-strict-cacheability-criteria, cache-poisoning-lab-web-cache-poisoning-combining-vulnerabilities"}),e[7]||(e[7]=a("h2",{id:"internal-caches",tabindex:"-1"},[i("Internal caches "),a("a",{class:"header-anchor",href:"#internal-caches","aria-label":'Permalink to "Internal caches"'},"​")],-1)),e[8]||(e[8]=a("p",null,"Not all caches are CDNs. Application-level caches, reverse proxies, and fragment caches can be poisoned through headers or parameters that never reach the edge.",-1)),n(o,{ids:"cache-poisoning-lab-web-cache-poisoning-internal"}),e[9]||(e[9]=s('<details class="details custom-block"><summary>⚙️ Engine Variations: cache implementations</summary><ul><li><strong>Varnish:</strong> <code>vcl_hash</code> defines the key; unkeyed headers are common when <code>vcl_recv</code> normalises them away.</li><li><strong>Nginx <code>proxy_cache_key</code>:</strong> often <code>$scheme$host$request_uri</code>; query strings are included, headers are not.</li><li><strong>Cloudflare:</strong> default key includes host, path, and query; <code>Vary</code> and cache rules can change it.</li><li><strong>Akamai:</strong> property rules decide which headers/query params are in the key.</li><li><strong>Fastly:</strong> VCL controls the key explicitly; <code>Vary</code> is honoured only if configured.</li></ul><p>Poisoning is a configuration property, not a product vulnerability.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Do not reflect unkeyed inputs into cacheable responses. Normalise the request before keying, and make the origin and cache agree on delimiters. Send <code>Cache-Control: private, no-store</code> for personalised pages. Use <code>Vary</code> for headers that affect the response. Purge aggressively after deploys. Treat the cache as part of the trust boundary.</p></div>',2)),n(r,{"topic-id":"web-cache-poisoning",label:"Mark cache poisoning complete"})])}const w=c(h,[["render",p]]);export{f as __pageData,w as default};
